const upCap=()=>UP_CAPS[Math.min(upCapLevel(),UP_CAPS.length)-1];
let sqBack=null,sqSel={t:'s',k:'QB'},sqTab='stats';
const PRIM={QB:'QB',RB:'RB',WR:'WR1',TE:'TE',OL:'OL1'};
