    rec.forEach((id,i)=>{const w=1+i*ADAPT_RECENCY;tot+=w;{const pk=PLAYS.find(q=>q.id===id)||{};if(pk.kind==='run')run+=w;else if(pk.kind==='pass'){pass+=w;if(pk.deepish)deep+=w}}});
