      Q(f0-.03,v0-.4,f1+.03,v1+.4,'#05040c');Q(f0,v0,f1,v1,nrgba(sc,.7*fl));Q(f0,v0,f1,v0+(v1-v0)*.5,'rgba(0,0,0,.28)');
      const m1=pt(f0,v0),m2=pt(f1,v1);Q(f0,v0,f1,v1,scanPat());
