    g.fillStyle='rgba(232,163,61,.12)';g.beginPath();g.moveTo(tx,ty-hh*.37);g.lineTo(tx-W*.22,ty-hh*.5);g.lineTo(tx-W*.22,ty-hh*.3);g.closePath();g.fill();   // its static beam (12%)
