      ctx.fillStyle='#0d0a08';ctx.beginPath();ctx.moveTo(q.sx,bot);ctx.lineTo(q2.sx,q2.sy-2.8*q2.u);ctx.lineTo(q2.sx,q2.sy-5*q2.u);ctx.lineTo(q.sx,top);ctx.closePath();ctx.fill();
