const SHK=window.SHK={tr:0,max:16,rot:.014,decay:2.2,dx:0,dy:0};
function bmShake(a,dx,dy){SHK.tr=Math.min(1,SHK.tr+a*(bmLite()?.4:1));if(dx!==undefined){SHK.dx=dx;SHK.dy=dy||0}}
