  const civ=id==='zd'?'runner':'courier',C=Object.assign({},CIV[civ]||{},HB_CIV[civ]||{}),pl=ktFind(id==='zd'?/Zero Day/:/Riptide/)||{name:id==='zd'?'"Zero Day" Darnell Reyes':'"Riptide" Sterling',pos:id==='zd'?'WR':'RB'};
