const RIP3={tape14:1,satchel:1,hat3:'none',hair3:'short',hairC3:'#1a1410',noBeard3:1,bw3:13},ZD3={zd:1,hat3:'none',hair3:'curly',hairC3:'#2a1a10',noBeard3:1};
