 [5,21,10,5,105,140,230,.62],   // canal: calm, dimmer, bluish
 [12,28,5,5,150,115,105,.62],   // home: cozy, dim
 [16,36,14,5,140,115,115,.66],  // south quiet blocks: dim
 [6,28,6,5,140,190,180,.35]     // tower side: shaded
