      ctx.save();
      ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(pr.sx,pr.sy,rw*1.1,rw*.42,0,0,7);ctx.fill();
      ctx.fillStyle='#9b3d20';ctx.fillRect(pr.sx-rw*.6,pr.sy-rh,rw*1.2,rh);
